public int search(int[] nums, int target) {
    int left = 0;
    int right = nums.length - 1;
    while (left <= right) {
        int mid = (left + right) / 2;
        if (nums[mid] == target) {
            return mid;
        }
        if (nums[mid] >= nums[left]) {
            if (target >= nums[left] && target < nums[mid]) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        } else {
            if (target > nums[mid] && target <= nums[right]) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
    }
    return -1;
}

public double trimMean(int[] arr) {
    // Calculate the mean of the remaining elements after removing the smallest 5% and largest 5% of the elements
    // Return the mean with an error within 10^-5

    // Step 1: Sort the array in ascending order
    Arrays.sort(arr);

    // Step 2: Calculate the number of elements to remove from the smallest and largest ends
    int numToRemove = (int) Math.round(arr.length * 0.05);

    // Step 3: Remove the smallest and largest elements
    int[] trimmedArr = Arrays.copyOfRange(arr, numToRemove, arr.length - numToRemove);

    // Step 4: Calculate the mean of the trimmed array
    double mean = 0.0;
    for (int i = 0; i < trimmedArr.length; i++) {
        mean += trimmedArr[i];
    }
    mean /= trimmedArr.length;

    // Step 5: Return the mean with an error within 10^-5
    return mean;
}

