public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize the minimum time required to collect all apples and return to node 0
    int minTime = 0;

    // Initialize a boolean array to keep track of the visited nodes
    boolean[] visited = new boolean[n];

    // Initialize a queue to perform BFS
    Queue<Integer> queue = new LinkedList<>();

    // Mark node 0 as visited and add it to the queue
    visited[0] = true;
    queue.add(0);

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the current node from the queue
        int currentNode = queue.poll();

        // Loop through all the neighbors of the current node
        for (int neighbor : edges[currentNode]) {
            // If the neighbor has an apple, add the time required to collect it to the minimum time
            if (hasApple[neighbor]) {
                minTime += 2;
            }

            // If the neighbor has not been visited, mark it as visited and add it to the queue
            if (!visited[neighbor]) {
                visited[neighbor] = true;
                queue.add(neighbor);
            }
        }
    }

    // Return the minimum time required to collect all apples and return to node 0
    return minTime;
}

