public int minOperations(int n) {
    int[] arr = new int[n];
    for (int i = 0; i < n; i++) {
        arr[i] = (2 * i) + 1;
    }

    int minOperations = 0;
    while (!allEqual(arr)) {
        int x = -1, y = -1;
        for (int i = 0; i < n; i++) {
            if (arr[i] != arr[0]) {
                x = i;
                break;
            }
        }
        for (int i = n - 1; i >= 0; i--) {
            if (arr[i] != arr[n - 1]) {
                y = i;
                break;
            }
        }
        if (x == -1 || y == -1) {
            break;
        }
        arr[x] -= 1;
        arr[y] += 1;
        minOperations++;
    }

    return minOperations;
}

private boolean allEqual(int[] arr) {
    for (int i = 1; i < arr.length; i++) {
        if (arr[i] != arr[0]) {
            return false;
        }
    }
    return true;
}

