public String getSmallestString(int n, int k) {
    if (n < 1 || k < 1) {
        throw new IllegalArgumentException("n and k must be positive integers");
    }
    if (n > 26) {
        throw new IllegalArgumentException("n must be less than or equal to 26");
    }
    if (k > (n * (n + 1)) / 2) {
        throw new IllegalArgumentException("k must be less than or equal to (n * (n + 1)) / 2");
    }

    StringBuilder sb = new StringBuilder();
    int remaining = k;
    for (int i = 0; i < n; i++) {
        int charValue = Math.min(remaining, 26 - i);
        sb.append((char) ('a' + charValue - 1));
        remaining -= charValue;
    }

    return sb.toString();
}

