    int x2 = points[1][0];
    int y2 = points[1][1];
    int x3 = points[2][0];
    int y3 = points[2][1];

    if (x1 == x2 && y1 == y2) {
        return false;
    }
    if (x2 == x3 && y2 == y3) {
        return false;
    }
    if (x1 == x3 && y1 == y3) {
        return false;
    }

    int slope1 = (y2 - y1) / (x2 - x1);
    int slope2 = (y3 - y2) / (x3 - x2);

    if (slope1 == slope2) {
        return false;
    }

    int intercept1 = y1 - (slope1 * x1);
    int intercept2 = y2 - (slope2 * x2);

    if (intercept1 == intercept2) {
        return false;
    }

    return true;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer.");
    }
    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    for (int i = 1; i < n; i++) {
        int min = Math.min(uglyNumbers[i2] * 2, Math.min(uglyNumbers[i3] * 3, uglyNumbers[i5] * 5));
        uglyNumbers[i] = min;
        if (min == uglyNumbers[i2] * 2) {
            i2++;
        }
        if (min == uglyNumbers[i3] * 3) {
            i3++;
        }
        if (min == uglyNumbers[i5] * 5) {
            i5++;
        }
    }
    return uglyNumbers[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int energy = 0;
    int currentLength = 0;
    char currentChar = s.charAt(0);
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == currentChar) {
            currentLength++;
        } else {
            if (currentLength > energy) {
                energy = currentLength;
            }
            currentChar = s.charAt(i);
            currentLength = 1;
        }
    }
    if (currentLength > energy) {
        energy = currentLength;
    }
    return energy;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= n; i++) {
