public static int calculateUniqueSum(int[] nums) {
    Set<Integer> uniqueNums = new HashSet<>();
    for (int num : nums) {
        uniqueNums.add(num);
    }
    int sum = 0;
    for (int num : uniqueNums) {
        sum += num;
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    int minSquares = Integer.MAX_VALUE;
    for (int i = 1; i <= n; i++) {
        int perfectSquare = i * i;
        if (perfectSquare > n) {
            break;
        }
        int remaining = n - perfectSquare;
        int squares = 1 + minPerfectSquareSum(remaining);
        minSquares = Math.min(minSquares, squares);
    }
    return minSquares;
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    StringBuilder result = new StringBuilder();
    for (String word : words) {
        result.append(new StringBuilder(word).reverse().toString() + " ");
    }
    return result.toString().trim();
}
